              "{\"headline\":\"Trump prepared to hit China with $60 billion in annual tariffs\",\"alternativeHeadline\":\"Trump prepared to hit China with $60 billion in annual tariffs\",\"dateModified\":\"2018-03-20T14:34:32.512Z\",\"datePublished\":\"2018-03-19T21:25:21.000Z\",\"author\":[{\"name\":\"Damian Paletta\"},{\"name\":\"Steven Mufson\"},{\"name\":\"Josh Dawsey\"}],\"isPartOf\":{\"name\":\"The Washington Post\",\"productID\":\"washingtonpost.com:basic\",\"description\":\"Breaking news and analysis on politics, business, world, national news, entertainment and more. In-depth DC, Virginia, Maryland news coverage including traffic, weather, crime, education, restaurant reviews and more.\",\"sku\":\"https://subscribe.washingtonpost.com\",\"brand\":{\"name\":\"The Washington Post\"}},\"publisher\":{\"name\":\"The Washington Post\"},\"isAccessibleForFree\":false,\"hasPart\":{\"isAccessibleForFree\":false},\"keywords\":\"business, china, trump trade, trump tariffs, steel tariffs, trump, the treasury department, america first, gary cohn, chinese\"}"
            ]
